@page "/apply"
@using sv_dce1f65f05a04b47a0e274dfb7df14dd.Models
@using sv_dce1f65f05a04b47a0e274dfb7df14dd.Services
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    @* ───── Step Indicator Bar ───── *@
    <nav class="d-flex justify-content-between mb-4 position-relative">
        <div class="position-absolute" style="top: 20px; left: 40px; right: 40px; height: 2px; background: #dee2e6; z-index: 0;"></div>
        @for (int i = 0; i < _stepLabels.Length; i++)
        {
            var step = i;
            var isCompleted = step < _currentStep;
            var isCurrent = step == _currentStep;
            var isFuture = step > _currentStep;
            var canClick = isCompleted && !_submitted;

            <div class="text-center position-relative" style="z-index: 1; flex: 1;">
                <button type="button"
                        class="btn rounded-circle d-inline-flex align-items-center justify-content-center border-0 @(isCurrent ? "btn-primary" : isCompleted ? "btn-success" : "btn-secondary opacity-50")"
                        style="width: 40px; height: 40px; font-size: 0.85rem;"
                        disabled="@(!canClick)"
                        @onclick="() => GoToStep(step)">
                    @if (isCompleted)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@(step + 1)</span>
                    }
                </button>
                <div class="small mt-1 @(isFuture ? "text-muted" : "") @(isCurrent ? "fw-bold" : "")">
                    @_stepLabels[step]
                </div>
            </div>
        }
    </nav>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="alert alert-danger">@_errorMessage</div>
    }

    @* ───── Step 1: Personal Info ───── *@
    @if (_currentStep == 0)
    {
        <div class="card">
            <div class="card-body">
                <h4 class="card-title mb-3">Personal Information</h4>

                <div class="mb-3">
                    <label class="form-label">Full Name <span class="text-danger">*</span></label>
                    <input class="form-control" @bind="_fullName" @bind:event="oninput" placeholder="Jane Doe" />
                </div>

                <div class="mb-3">
                    <label class="form-label">Email <span class="text-danger">*</span></label>
                    <input type="email" class="form-control" @bind="_email" @bind:event="oninput" placeholder="jane@example.com" />
                    @if (_emailValidating)
                    {
                        <div class="form-text text-info">Validating email…</div>
                    }
                </div>

                <div class="mb-3">
                    <label class="form-label">Phone <span class="text-danger">*</span></label>
                    <input type="tel" class="form-control" @bind="_phone" @bind:event="oninput" placeholder="(555) 123-4567" />
                </div>

                <div class="mb-3">
                    <label class="form-label">Address <span class="text-danger">*</span></label>
                    <textarea class="form-control" rows="2" @bind="_address" @bind:event="oninput" placeholder="123 Main St, City, State ZIP"></textarea>
                </div>

                <div class="d-flex justify-content-end">
                    <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@_emailValidating">
                        Next &raquo;
                    </button>
                </div>
            </div>
        </div>
    }

    @* ───── Step 2: Work History ───── *@
    @if (_currentStep == 1)
    {
        <div class="card">
            <div class="card-body">
                <h4 class="card-title mb-3">Work History</h4>

                @for (int i = 0; i < _workEntries.Count; i++)
                {
                    var idx = i;
                    var entry = _workEntries[idx];

                    <div class="border rounded p-3 mb-3 bg-light">
                        <div class="d-flex justify-content-between align-items-center mb-2">
                            <h6 class="mb-0">Position @(idx + 1)</h6>
                            @if (_workEntries.Count > 1)
                            {
                                <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveWorkEntry(idx)">Remove</button>
                            }
                        </div>

                        <div class="row mb-2">
                            <div class="col-md-6">
                                <label class="form-label">Company <span class="text-danger">*</span></label>
                                <input class="form-control" value="@entry.Company"
                                       @onchange="e => UpdateWork(idx, entry with { Company = e.Value?.ToString() ?? "" })" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Job Title <span class="text-danger">*</span></label>
                                <input class="form-control" value="@entry.Title"
                                       @onchange="e => UpdateWork(idx, entry with { Title = e.Value?.ToString() ?? "" })" />
                            </div>
                        </div>

                        <div class="row mb-2">
                            <div class="col-md-4">
                                <label class="form-label">Start Date <span class="text-danger">*</span></label>
                                <input type="date" class="form-control" value="@(entry.StartDate == default ? "" : entry.StartDate.ToString("yyyy-MM-dd"))"
                                       @onchange="e => UpdateWork(idx, entry with { StartDate = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : entry.StartDate })" />
                            </div>
                            <div class="col-md-4">
                                <label class="form-label">End Date</label>
                                <input type="date" class="form-control" value="@(entry.EndDate?.ToString("yyyy-MM-dd") ?? "")"
                                       disabled="@entry.IsCurrent"
                                       @onchange="e => UpdateWork(idx, entry with { EndDate = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null })" />
                            </div>
                            <div class="col-md-4 d-flex align-items-end mb-1">
                                <div class="form-check">
                                    <input type="checkbox" class="form-check-input" id="current-@idx" checked="@entry.IsCurrent"
                                           @onchange="e => UpdateWork(idx, entry with { IsCurrent = (bool)(e.Value ?? false), EndDate = (bool)(e.Value ?? false) ? null : entry.EndDate })" />
                                    <label class="form-check-label" for="current-@idx">Currently working here</label>
                                </div>
                            </div>
                        </div>

                        <div class="mb-0">
                            <label class="form-label">Description</label>
                            <textarea class="form-control" rows="2" value="@entry.Description"
                                      @onchange="e => UpdateWork(idx, entry with { Description = e.Value?.ToString() ?? "" })"></textarea>
                        </div>
                    </div>
                }

                <button class="btn btn-outline-primary btn-sm mb-3" @onclick="AddWorkEntry">
                    + Add Another Position
                </button>

                <div class="d-flex justify-content-between">
                    <button class="btn btn-secondary" @onclick="PreviousStep">&laquo; Back</button>
                    <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next &raquo;</button>
                </div>
            </div>
        </div>
    }

    @* ───── Step 3: References ───── *@
    @if (_currentStep == 2)
    {
        <div class="card">
            <div class="card-body">
                <h4 class="card-title mb-3">References</h4>

                @for (int i = 0; i < _references.Count; i++)
                {
                    var idx = i;
                    var refEntry = _references[idx];

                    <div class="border rounded p-3 mb-3 bg-light">
                        <div class="d-flex justify-content-between align-items-center mb-2">
                            <h6 class="mb-0">Reference @(idx + 1)</h6>
                            @if (_references.Count > 2)
                            {
                                <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(idx)">Remove</button>
                            }
                        </div>

                        <div class="row mb-2">
                            <div class="col-md-6">
                                <label class="form-label">Name <span class="text-danger">*</span></label>
                                <input class="form-control" value="@refEntry.Name"
                                       @onchange="e => UpdateReference(idx, refEntry with { Name = e.Value?.ToString() ?? "" })" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Relationship <span class="text-danger">*</span></label>
                                <input class="form-control" value="@refEntry.Relationship"
                                       @onchange="e => UpdateReference(idx, refEntry with { Relationship = e.Value?.ToString() ?? "" })" />
                            </div>
                        </div>

                        <div class="row">
                            <div class="col-md-6">
                                <label class="form-label">Email <span class="text-danger">*</span></label>
                                <input type="email" class="form-control" value="@refEntry.Email"
                                       @onchange="e => UpdateReference(idx, refEntry with { Email = e.Value?.ToString() ?? "" })" />
                            </div>
                            <div class="col-md-6">
                                <label class="form-label">Phone <span class="text-danger">*</span></label>
                                <input type="tel" class="form-control" value="@refEntry.Phone"
                                       @onchange="e => UpdateReference(idx, refEntry with { Phone = e.Value?.ToString() ?? "" })" />
                            </div>
                        </div>
                    </div>
                }

                @if (_references.Count < 3)
                {
                    <button class="btn btn-outline-primary btn-sm mb-3" @onclick="AddReference">
                        + Add Reference
                    </button>
                }

                <div class="d-flex justify-content-between">
                    <button class="btn btn-secondary" @onclick="PreviousStep">&laquo; Back</button>
                    <button class="btn btn-primary" @onclick="NextFromReferences">Next &raquo;</button>
                </div>
            </div>
        </div>
    }

    @* ───── Step 4: Cover Letter ───── *@
    @if (_currentStep == 3)
    {
        <div class="card">
            <div class="card-body">
                <h4 class="card-title mb-3">Cover Letter</h4>

                <div class="mb-2">
                    <textarea class="form-control" rows="10" maxlength="2000"
                              @bind="_coverLetter" @bind:event="oninput"
                              placeholder="Tell us why you're a great fit for this role…"></textarea>
                </div>
                <div class="form-text text-end mb-3">
                    @(_coverLetter?.Length ?? 0) / 2000 characters
                </div>

                <div class="d-flex justify-content-between">
                    <button class="btn btn-secondary" @onclick="PreviousStep">&laquo; Back</button>
                    <button class="btn btn-primary" @onclick="NextFromCoverLetter">Next &raquo;</button>
                </div>
            </div>
        </div>
    }

    @* ───── Step 5: Review & Submit ───── *@
    @if (_currentStep == 4)
    {
        <div class="card">
            <div class="card-body">
                <h4 class="card-title mb-4">Review &amp; Submit</h4>

                @if (_submitted)
                {
                    <div class="alert alert-success text-center">
                        <h5 class="mb-2">&#10003; Application Submitted!</h5>
                        <p class="mb-0">Your application ID is <strong>@_applicationId</strong>. We will be in touch.</p>
                    </div>
                }
                else
                {
                    @* Personal Info Section *@
                    <div class="mb-4">
                        <div class="d-flex justify-content-between align-items-center border-bottom pb-1 mb-2">
                            <h5 class="mb-0">Personal Information</h5>
                            <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(0)">Edit</button>
                        </div>
                        <dl class="row mb-0">
                            <dt class="col-sm-3">Name</dt><dd class="col-sm-9">@_fullName</dd>
                            <dt class="col-sm-3">Email</dt><dd class="col-sm-9">@_email</dd>
                            <dt class="col-sm-3">Phone</dt><dd class="col-sm-9">@_phone</dd>
                            <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@_address</dd>
                        </dl>
                    </div>

                    @* Work History Section *@
                    <div class="mb-4">
                        <div class="d-flex justify-content-between align-items-center border-bottom pb-1 mb-2">
                            <h5 class="mb-0">Work History</h5>
                            <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(1)">Edit</button>
                        </div>
                        @foreach (var entry in _workEntries)
                        {
                            <div class="mb-2">
                                <strong>@entry.Title</strong> at @entry.Company<br />
                                <span class="text-muted">
                                    @entry.StartDate.ToString("MMM yyyy") &ndash;
                                    @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                                </span>
                                @if (!string.IsNullOrWhiteSpace(entry.Description))
                                {
                                    <p class="mb-0 mt-1">@entry.Description</p>
                                }
                            </div>
                        }
                    </div>

                    @* References Section *@
                    <div class="mb-4">
                        <div class="d-flex justify-content-between align-items-center border-bottom pb-1 mb-2">
                            <h5 class="mb-0">References</h5>
                            <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(2)">Edit</button>
                        </div>
                        @foreach (var refEntry in _references)
                        {
                            <div class="mb-2">
                                <strong>@refEntry.Name</strong> (@refEntry.Relationship)<br />
                                <span class="text-muted">@refEntry.Email &bull; @refEntry.Phone</span>
                            </div>
                        }
                    </div>

                    @* Cover Letter Section *@
                    <div class="mb-4">
                        <div class="d-flex justify-content-between align-items-center border-bottom pb-1 mb-2">
                            <h5 class="mb-0">Cover Letter</h5>
                            <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(3)">Edit</button>
                        </div>
                        <p style="white-space: pre-wrap;">@_coverLetter</p>
                    </div>

                    <div class="d-flex justify-content-between">
                        <button class="btn btn-secondary" @onclick="PreviousStep">&laquo; Back</button>
                        <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_submitting">
                            @if (_submitting)
                            {
                                <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                                <span>Submitting…</span>
                            }
                            else
                            {
                                <span>Submit Application</span>
                            }
                        </button>
                    </div>
                }
            </div>
        </div>
    }
</div>

@code {
    private static readonly string[] _stepLabels = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int _currentStep;
    private string? _errorMessage;

    // Step 1 state
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";
    private bool _emailValidating;

    // Step 2 state
    private List<WorkEntryModel> _workEntries = new() { new() };

    // Step 3 state
    private List<ReferenceModel> _references = new() { new(), new() };

    // Step 4 state
    private string _coverLetter = "";

    // Step 5 state
    private bool _submitting;
    private bool _submitted;
    private int _applicationId;

    // ── Mutable model wrappers for form binding ──

    private record WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }

    private record ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }

    // ── Navigation ──

    private void GoToStep(int step)
    {
        _errorMessage = null;
        _currentStep = step;
    }

    private void PreviousStep()
    {
        _errorMessage = null;
        _currentStep--;
    }

    // ── Step 1 ──

    private async Task NextFromPersonalInfo()
    {
        _errorMessage = null;

        if (string.IsNullOrWhiteSpace(_fullName) || string.IsNullOrWhiteSpace(_email)
            || string.IsNullOrWhiteSpace(_phone) || string.IsNullOrWhiteSpace(_address))
        {
            _errorMessage = "Please fill in all required fields.";
            return;
        }

        _emailValidating = true;
        try
        {
            var valid = await ApplicationService.ValidateEmailAsync(_email);
            if (!valid)
            {
                _errorMessage = "Please enter a valid email address.";
                return;
            }
        }
        finally
        {
            _emailValidating = false;
        }

        _currentStep = 1;
    }

    // ── Step 2 ──

    private void UpdateWork(int index, WorkEntryModel updated) => _workEntries[index] = updated;

    private void AddWorkEntry() => _workEntries.Add(new());

    private void RemoveWorkEntry(int index) => _workEntries.RemoveAt(index);

    private void NextFromWorkHistory()
    {
        _errorMessage = null;

        foreach (var entry in _workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title)
                || entry.StartDate == default)
            {
                _errorMessage = "Please fill in company, title, and start date for every position.";
                return;
            }
        }

        _currentStep = 2;
    }

    // ── Step 3 ──

    private void UpdateReference(int index, ReferenceModel updated) => _references[index] = updated;

    private void AddReference()
    {
        if (_references.Count < 3) _references.Add(new());
    }

    private void RemoveReference(int index) => _references.RemoveAt(index);

    private void NextFromReferences()
    {
        _errorMessage = null;

        foreach (var r in _references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                _errorMessage = "Please fill in all fields for every reference.";
                return;
            }
        }

        _currentStep = 3;
    }

    // ── Step 4 ──

    private void NextFromCoverLetter()
    {
        _errorMessage = null;

        if (string.IsNullOrWhiteSpace(_coverLetter))
        {
            _errorMessage = "Please write a cover letter before proceeding.";
            return;
        }

        _currentStep = 4;
    }

    // ── Step 5 ──

    private async Task SubmitApplication()
    {
        _errorMessage = null;
        _submitting = true;

        try
        {
            var application = new JobApplication(
                new PersonalInfo(_fullName, _email, _phone, _address),
                new WorkHistory(_workEntries.Select(e =>
                    new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList()),
                _references.Select(r =>
                    new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
                _coverLetter
            );

            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _submitted = true;
        }
        catch (Exception ex)
        {
            _errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _submitting = false;
        }
    }
}

